/** bool8 ObjectEventIsTrainerAndCloseToPlayer(struct ObjectEvent *objectEvent) */
export function ObjectEventIsTrainerAndCloseToPlayer(objectEvent: any): any {
  let playerX: any = null;
      let playerY: any = null;
      let objX: any = null;
      let objY: any = null;
      let minX: any = null;
      let maxX: any = null;
      let minY: any = null;
      let maxY: any = null;

      if (!TestPlayerAvatarFlags(PLAYER_AVATAR_FLAG_DASH))
          return FALSE;

      if (objectEvent.trainerType != TRAINER_TYPE_NORMAL && objectEvent.trainerType != TRAINER_TYPE_BURIED)
          return FALSE;

      PlayerGetDestCoords(playerX,playerY);
      objX = objectEvent.currentCoords.x;
      objY = objectEvent.currentCoords.y;
      minX = objX - objectEvent.trainerRange_berryTreeId;
      minY = objY - objectEvent.trainerRange_berryTreeId;
      maxX = objX + objectEvent.trainerRange_berryTreeId;
      maxY = objY + objectEvent.trainerRange_berryTreeId;
      if (minX > playerX || maxX < playerX
       || minY > playerY || maxY < playerY)
          return FALSE;

      return TRUE;
}

/** u8 GetVectorDirection(s16 dx, s16 dy, s16 absdx, s16 absdy) */
export function GetVectorDirection(dx: any, dy: any, absdx: any, absdy: any): any {
  let direction: any = null;

      if (absdx > absdy)
      {
          direction = DIR_EAST;
          if (dx < 0)
              direction = DIR_WEST;
      }
      else
      {
          direction = DIR_SOUTH;
          if (dy < 0)
              direction = DIR_NORTH;
      }
      return direction;
}

/** u8 GetLimitedVectorDirection_SouthNorth(s16 dx, s16 dy, s16 absdx, s16 absdy) */
export function GetLimitedVectorDirection_SouthNorth(dx: any, dy: any, absdx: any, absdy: any): any {
  let direction: any = null;

      direction = DIR_SOUTH;
      if (dy < 0)
          direction = DIR_NORTH;
      return direction;
}

/** u8 GetLimitedVectorDirection_WestEast(s16 dx, s16 dy, s16 absdx, s16 absdy) */
export function GetLimitedVectorDirection_WestEast(dx: any, dy: any, absdx: any, absdy: any): any {
  let direction: any = null;

      direction = DIR_EAST;
      if (dx < 0)
          direction = DIR_WEST;
      return direction;
}

/** u8 GetLimitedVectorDirection_WestNorth(s16 dx, s16 dy, s16 absdx, s16 absdy) */
export function GetLimitedVectorDirection_WestNorth(dx: any, dy: any, absdx: any, absdy: any): any {
  let direction: any = null;

      direction = GetVectorDirection(dx, dy, absdx, absdy);
      if (direction == DIR_SOUTH)
      {
          direction = GetLimitedVectorDirection_WestEast(dx, dy, absdx, absdy);
          if (direction == DIR_EAST)
              direction = DIR_NORTH;
      }
      else if (direction == DIR_EAST)
      {
          direction = GetLimitedVectorDirection_SouthNorth(dx, dy, absdx, absdy);
          if (direction == DIR_SOUTH)
              direction = DIR_NORTH;
      }
      return direction;
}

