/** static u8 GetCollisionInDirection(struct ObjectEvent *objectEvent, u8 direction) */
export function GetCollisionInDirection(objectEvent: any, direction: any): any {
  let x: any = objectEvent.currentCoords.x;
      let y: any = objectEvent.currentCoords.y;
      MoveCoords(direction,x,y);
      return GetCollisionAtCoords(objectEvent, x, y, direction);
}

/** u8 GetCollisionAtCoords(struct ObjectEvent *objectEvent, s16 x, s16 y, u32 dir) */
export function GetCollisionAtCoords(objectEvent: any, x: any, y: any, dir: any): any {
  let direction: any = dir;
      if (IsCoordOutsideObjectEventMovementRange(objectEvent, x, y))
          return COLLISION_OUTSIDE_RANGE;
      else if (MapGridGetCollisionAt(x, y) || GetMapBorderIdAt(x, y) == CONNECTION_INVALID || IsMetatileDirectionallyImpassable(objectEvent, x, y, direction))
          return COLLISION_IMPASSABLE;
      else if (objectEvent.trackedByCamera && !CanCameraMoveInDirection(direction))
          return COLLISION_IMPASSABLE;
      else if (IsElevationMismatchAt(objectEvent.currentElevation, x, y))
          return COLLISION_ELEVATION_MISMATCH;
      else if (DoesObjectCollideWithObjectAt(objectEvent, x, y))
          return COLLISION_OBJECT_EVENT;
      return COLLISION_NONE;
}

/** u8 GetCollisionFlagsAtCoords(struct ObjectEvent *objectEvent, s16 x, s16 y, u8 direction) */
export function GetCollisionFlagsAtCoords(objectEvent: any, x: any, y: any, direction: any): any {
  let flags: any = 0;

      if (IsCoordOutsideObjectEventMovementRange(objectEvent, x, y))
          flags |= 1 << (COLLISION_OUTSIDE_RANGE - 1);
      if (MapGridGetCollisionAt(x, y) || GetMapBorderIdAt(x, y) == CONNECTION_INVALID || IsMetatileDirectionallyImpassable(objectEvent, x, y, direction) || (objectEvent.trackedByCamera && !CanCameraMoveInDirection(direction)))
          flags |= 1 << (COLLISION_IMPASSABLE - 1);
      if (IsElevationMismatchAt(objectEvent.currentElevation, x, y))
          flags |= 1 << (COLLISION_ELEVATION_MISMATCH - 1);
      if (DoesObjectCollideWithObjectAt(objectEvent, x, y))
          flags |= 1 << (COLLISION_OBJECT_EVENT - 1);
      return flags;
}

/** static bool8 IsCoordOutsideObjectEventMovementRange(struct ObjectEvent *objectEvent, s16 x, s16 y) */
export function IsCoordOutsideObjectEventMovementRange(objectEvent: any, x: any, y: any): any {
  let left: any = null;
      let right: any = null;
      let top: any = null;
      let bottom: any = null;

      if (objectEvent.range.rangeX != 0)
      {
          left = objectEvent.initialCoords.x - objectEvent.range.rangeX;
          right = objectEvent.initialCoords.x + objectEvent.range.rangeX;

          if (left > x || right < x)
              return TRUE;
      }
      if (objectEvent.range.rangeY != 0)
      {
          top = objectEvent.initialCoords.y - objectEvent.range.rangeY;
          bottom = objectEvent.initialCoords.y + objectEvent.range.rangeY;

          if (top > y || bottom < y)
              return TRUE;
      }
      return FALSE;
}

/** static bool8 IsMetatileDirectionallyImpassable(struct ObjectEvent *objectEvent, s16 x, s16 y, u8 direction) */
export function IsMetatileDirectionallyImpassable(objectEvent: any, x: any, y: any, direction: any): any {
  if (gOppositeDirectionBlockedMetatileFuncs[direction - 1](objectEvent.currentMetatileBehavior)
          || gDirectionBlockedMetatileFuncs[direction - 1](MapGridGetMetatileBehaviorAt(x, y)))
          return TRUE;

      return FALSE;
}

/** static bool8 DoesObjectCollideWithObjectAt(struct ObjectEvent *objectEvent, s16 x, s16 y) */
export function DoesObjectCollideWithObjectAt(objectEvent: any, x: any, y: any): any {
  let i: any = null;
      let curObject: any = null;

      for (i = 0; i < OBJECT_EVENTS_COUNT; i++)
      {
          curObject =gObjectEvents[i];
          if (curObject.active && curObject != objectEvent)
          {
              if ((curObject.currentCoords.x == x && curObject.currentCoords.y == y) || (curObject.previousCoords.x == x && curObject.previousCoords.y == y))
              {
                  if (AreElevationsCompatible(objectEvent.currentElevation, curObject.currentElevation))
                      return TRUE;
              }
          }
      }
      return FALSE;
}

/** bool8 IsBerryTreeSparkling(u8 localId, u8 mapNum, u8 mapGroup) */
export function IsBerryTreeSparkling(localId: any, mapNum: any, mapGroup: any): any {
  let objectEventId: any = null;

      if (!TryGetObjectEventIdByLocalIdAndMap(localId, mapNum, mapGroup,objectEventId)
          && gSprites[gObjectEvents[objectEventId].spriteId].sBerryTreeFlags & BERRY_FLAG_SPARKLING)
          return TRUE;

      return FALSE;
}

/** void SetBerryTreeJustPicked(u8 localId, u8 mapNum, u8 mapGroup) */
export function SetBerryTreeJustPicked(localId: any, mapNum: any, mapGroup: any): any {
  let objectEventId: any = null;

      if (!TryGetObjectEventIdByLocalIdAndMap(localId, mapNum, mapGroup,objectEventId))
          gSprites[gObjectEvents[objectEventId].spriteId].sBerryTreeFlags |= BERRY_FLAG_JUST_PICKED;
}

/** void MoveCoords(u8 direction, s16 *x, s16 *y) */
export function MoveCoords(direction: any, x: any, y: any): any {
  x += sDirectionToVectors[direction].x;
      y += sDirectionToVectors[direction].y;
}

/** static void MoveCoordsInDirection(u32 dir, s16 *x, s16 *y, s16 deltaX, s16 deltaY) */
export function MoveCoordsInDirection(dir: any, x: any, y: any, deltaX: any, deltaY: any): any {
  let direction: any = dir;
      let dx2: any = deltaX;
      let dy2: any = deltaY;
      if (sDirectionToVectors[direction].x > 0)
          x += dx2;
      if (sDirectionToVectors[direction].x < 0)
          x -= dx2;
      if (sDirectionToVectors[direction].y > 0)
          y += dy2;
      if (sDirectionToVectors[direction].y < 0)
          y -= dy2;
}

/** void GetMapCoordsFromSpritePos(s16 x, s16 y, s16 *destX, s16 *destY) */
export function GetMapCoordsFromSpritePos(x: any, y: any, destX: any, destY: any): any {
  destX = (x - gSaveBlock1Ptr.pos.x) << 4;
      destY = (y - gSaveBlock1Ptr.pos.y) << 4;
      destX -= gTotalCameraPixelOffsetX;
      destY -= gTotalCameraPixelOffsetY;
}

/** void SetSpritePosToMapCoords(s16 mapX, s16 mapY, s16 *destX, s16 *destY) */
export function SetSpritePosToMapCoords(mapX: any, mapY: any, destX: any, destY: any): any {
  let dx: any = -gTotalCameraPixelOffsetX - gFieldCamera.x;
      let dy: any = -gTotalCameraPixelOffsetY - gFieldCamera.y;
      if (gFieldCamera.x > 0)
          dx += 16;

      if (gFieldCamera.x < 0)
          dx -= 16;

      if (gFieldCamera.y > 0)
          dy += 16;

      if (gFieldCamera.y < 0)
          dy -= 16;

      destX = ((mapX - gSaveBlock1Ptr.pos.x) << 4) + dx;
      destY = ((mapY - gSaveBlock1Ptr.pos.y) << 4) + dy;
}

/** void SetSpritePosToOffsetMapCoords(s16 *x, s16 *y, s16 dx, s16 dy) */
export function SetSpritePosToOffsetMapCoords(x: any, y: any, dx: any, dy: any): any {
  SetSpritePosToMapCoords(x, y, x, y);
      x += dx;
      y += dy;
}

/** static void GetObjectEventMovingCameraOffset(s16 *x, s16 *y) */
export function GetObjectEventMovingCameraOffset(x: any, y: any): any {
  x = 0;
      y = 0;

      if (gFieldCamera.x > 0)
          x++;

      if (gFieldCamera.x < 0)
          x--;

      if (gFieldCamera.y > 0)
          y++;

      if (gFieldCamera.y < 0)
          y--;
}

/** void ObjectEventMoveDestCoords(struct ObjectEvent *objectEvent, u32 direction, s16 *x, s16 *y) */
export function ObjectEventMoveDestCoords(objectEvent: any, direction: any, x: any, y: any): any {
  let newDirn: any = direction;
      x = objectEvent.currentCoords.x;
      y = objectEvent.currentCoords.y;
      MoveCoords(newDirn, x, y);
}

/** bool8 ObjectEventIsMovementOverridden(struct ObjectEvent *objectEvent) */
export function ObjectEventIsMovementOverridden(objectEvent: any): any {
  if (objectEvent.singleMovementActive || objectEvent.heldMovementActive)
          return TRUE;

      return FALSE;
}

/** bool8 ObjectEventIsHeldMovementActive(struct ObjectEvent *objectEvent) */
export function ObjectEventIsHeldMovementActive(objectEvent: any): any {
  if (objectEvent.heldMovementActive && objectEvent.movementActionId != MOVEMENT_ACTION_NONE)
          return TRUE;

      return FALSE;
}

/** bool8 ObjectEventSetHeldMovement(struct ObjectEvent *objectEvent, u8 movementActionId) */
export function ObjectEventSetHeldMovement(objectEvent: any, movementActionId: any): any {
  if (ObjectEventIsMovementOverridden(objectEvent))
          return TRUE;

      UnfreezeObjectEvent(objectEvent);
      objectEvent.movementActionId = movementActionId;
      objectEvent.heldMovementActive = TRUE;
      objectEvent.heldMovementFinished = FALSE;
      gSprites[objectEvent.spriteId].sActionFuncId = 0;
      return FALSE;
}

/** void ObjectEventForceSetHeldMovement(struct ObjectEvent *objectEvent, u8 movementActionId) */
export function ObjectEventForceSetHeldMovement(objectEvent: any, movementActionId: any): any {
  ObjectEventClearHeldMovementIfActive(objectEvent);
      ObjectEventSetHeldMovement(objectEvent, movementActionId);
}

/** void ObjectEventClearHeldMovementIfActive(struct ObjectEvent *objectEvent) */
export function ObjectEventClearHeldMovementIfActive(objectEvent: any): any {
  if (objectEvent.heldMovementActive)
          ObjectEventClearHeldMovement(objectEvent);
}

/** void ObjectEventClearHeldMovement(struct ObjectEvent *objectEvent) */
export function ObjectEventClearHeldMovement(objectEvent: any): any {
  objectEvent.movementActionId = MOVEMENT_ACTION_NONE;
      objectEvent.heldMovementActive = FALSE;
      objectEvent.heldMovementFinished = FALSE;
      gSprites[objectEvent.spriteId].sTypeFuncId = 0;
      gSprites[objectEvent.spriteId].sActionFuncId = 0;
}

/** u8 ObjectEventCheckHeldMovementStatus(struct ObjectEvent *objectEvent) */
export function ObjectEventCheckHeldMovementStatus(objectEvent: any): any {
  if (objectEvent.heldMovementActive)
          return objectEvent.heldMovementFinished;

      return 16;
}

/** u8 ObjectEventClearHeldMovementIfFinished(struct ObjectEvent *objectEvent) */
export function ObjectEventClearHeldMovementIfFinished(objectEvent: any): any {
  let heldMovementStatus: any = ObjectEventCheckHeldMovementStatus(objectEvent);
      if (heldMovementStatus != 0 && heldMovementStatus != 16)
          ObjectEventClearHeldMovementIfActive(objectEvent);

      return heldMovementStatus;
}

/** u8 ObjectEventGetHeldMovementActionId(struct ObjectEvent *objectEvent) */
export function ObjectEventGetHeldMovementActionId(objectEvent: any): any {
  if (objectEvent.heldMovementActive)
          return objectEvent.movementActionId;

      return MOVEMENT_ACTION_NONE;
}

/** void UpdateObjectEventCurrentMovement(struct ObjectEvent *objectEvent, struct Sprite *sprite, bool8 (*callback)(struct ObjectEvent *, struct Sprite *)) */
export function UpdateObjectEventCurrentMovement(objectEvent: any, sprite: any, callback: any): any {
  DoGroundEffects_OnSpawn(objectEvent, sprite);
      TryEnableObjectEventAnim(objectEvent, sprite);

      if (ObjectEventIsHeldMovementActive(objectEvent))
          ObjectEventExecHeldMovementAction(objectEvent, sprite);
      else if (!objectEvent.frozen)
          while (callback(objectEvent, sprite));

      DoGroundEffects_OnBeginStep(objectEvent, sprite);
      DoGroundEffects_OnFinishStep(objectEvent, sprite);
      UpdateObjectEventSpriteAnimPause(objectEvent, sprite);
      UpdateObjectEventVisibility(objectEvent, sprite);
      ObjectEventUpdateSubpriority(objectEvent, sprite);
}

/** bool8 ObjectEventFaceOppositeDirection(struct ObjectEvent *objectEvent, u8 direction) */
export function ObjectEventFaceOppositeDirection(objectEvent: any, direction: any): any {
  return ObjectEventSetHeldMovement(objectEvent, GetFaceDirectionMovementAction(GetOppositeDirection(direction)));
}

/** u8 GetOppositeDirection(u8 direction) */
export function GetOppositeDirection(direction: any): any {
  const directions: any[] = [];

      memcpy(directions, sOppositeDirections, 0);
      if (direction <= DIR_NONE || direction > (0))
          return direction;

      return directions[direction - 1];
}

/** static u32 GetPlayerDirectionForCopy(u8 initDir, u8 moveDir) */
export function GetPlayerDirectionForCopy(initDir: any, moveDir: any): any {
  return sPlayerDirectionsForCopy[initDir - 1][moveDir - 1];
}

/** static u32 GetCopyDirection(u8 copyInitDir, u32 playerInitDir, u32 playerMoveDir) */
export function GetCopyDirection(copyInitDir: any, playerInitDir: any, playerMoveDir: any): any {
  let dir: any = null;
      let _playerInitDir: any = playerInitDir;
      let _playerMoveDir: any = playerMoveDir;
      if (_playerInitDir == DIR_NONE || _playerMoveDir == DIR_NONE
        || _playerInitDir > DIR_EAST || _playerMoveDir > DIR_EAST)
          return DIR_NONE;

      dir = GetPlayerDirectionForCopy(_playerInitDir, playerMoveDir);
      return sPlayerDirectionToCopyDirection[copyInitDir - 1][dir - 1];
}

/** static void ObjectEventExecHeldMovementAction(struct ObjectEvent *objectEvent, struct Sprite *sprite) */
export function ObjectEventExecHeldMovementAction(objectEvent: any, sprite: any): any {
  if (gMovementActionFuncs[objectEvent.movementActionId][sprite.sActionFuncId](objectEvent, sprite))
          objectEvent.heldMovementFinished = TRUE;
}

/** static bool8 ObjectEventExecSingleMovementAction(struct ObjectEvent *objectEvent, struct Sprite *sprite) */
export function ObjectEventExecSingleMovementAction(objectEvent: any, sprite: any): any {
  if (gMovementActionFuncs[objectEvent.movementActionId][sprite.sActionFuncId](objectEvent, sprite))
      {
          objectEvent.movementActionId = MOVEMENT_ACTION_NONE;
          sprite.sActionFuncId = 0;
          return TRUE;
      }
      return FALSE;
}

