/** static void GetGroundEffectFlags_JumpLanding(struct ObjectEvent *objEvent, u32 *flags) */
export function GetGroundEffectFlags_JumpLanding(objEvent: any, flags: any): any {
  let MetatileFunc: any = null;

      const metatileFuncs: any = [
          MetatileBehavior_IsTallGrass,
          MetatileBehavior_IsLongGrass,
          MetatileBehavior_IsPuddle,
          MetatileBehavior_IsSurfableWaterOrUnderwater,
          MetatileBehavior_IsShallowFlowingWater,
          MetatileBehavior_IsATile,
      ];

      const jumpLandingFlags: any = [
          GROUND_EFFECT_FLAG_LAND_IN_TALL_GRASS,
          GROUND_EFFECT_FLAG_LAND_IN_LONG_GRASS,
          GROUND_EFFECT_FLAG_LAND_IN_SHALLOW_WATER,
          GROUND_EFFECT_FLAG_LAND_IN_DEEP_WATER,
          GROUND_EFFECT_FLAG_LAND_IN_SHALLOW_WATER,
          GROUND_EFFECT_FLAG_LAND_ON_NORMAL_GROUND,
      ];

      if (objEvent.landingJump && !objEvent.disableJumpLandingGroundEffect)
      {
          let i: any = null;

          for (i = 0; i < ARRAY_COUNT(metatileFuncs); i++)
          {
              if (metatileFuncs[i](objEvent.currentMetatileBehavior))
              {
                  flags |= jumpLandingFlags[i];
                  return;
              }
          }
      }
}

/** static u8 ObjectEventGetNearbyReflectionType(struct ObjectEvent *objEvent) */
export function ObjectEventGetNearbyReflectionType(objEvent: any): any {
  let info: any = GetObjectEventGraphicsInfo(objEvent.graphicsId);

       
      let width: any = (info.width + 8) >> 4;
      let height: any = (info.height + 8) >> 4;
      let i, j;
      let result, b;  
      let one: any = 1;

      for (i = 0; i < height; i++)
      {
          RETURN_REFLECTION_TYPE_AT(objEvent.currentCoords.x, objEvent.currentCoords.y + one + i)
          RETURN_REFLECTION_TYPE_AT(objEvent.previousCoords.x, objEvent.previousCoords.y + one + i)
          for (j = 1; j < width; j++)
          {
              RETURN_REFLECTION_TYPE_AT(objEvent.currentCoords.x + j, objEvent.currentCoords.y + one + i)
              RETURN_REFLECTION_TYPE_AT(objEvent.currentCoords.x - j, objEvent.currentCoords.y + one + i)
              RETURN_REFLECTION_TYPE_AT(objEvent.previousCoords.x + j, objEvent.previousCoords.y + one + i)
              RETURN_REFLECTION_TYPE_AT(objEvent.previousCoords.x - j, objEvent.previousCoords.y + one + i)
          }
      }

      return REFL_TYPE_NONE;
}

/** static u8 GetReflectionTypeByMetatileBehavior(u32 behavior) */
export function GetReflectionTypeByMetatileBehavior(behavior: any): any {
  if (MetatileBehavior_IsIce(behavior))
          return REFL_TYPE_ICE;
      else if (MetatileBehavior_IsReflective(behavior))
          return REFL_TYPE_WATER;
      else
          return REFL_TYPE_NONE;
}

/** u8 GetLedgeJumpDirection(s16 x, s16 y, u8 direction) */
export function GetLedgeJumpDirection(x: any, y: any, direction: any): any {
  const ledgeBehaviorFuncs: any = [ MetatileBehavior_IsJumpSouth, MetatileBehavior_IsJumpNorth, MetatileBehavior_IsJumpWest, MetatileBehavior_IsJumpEast,
      ];

      let behavior: any = null;
      let index: any = direction;

      if (index == DIR_NONE)
          return DIR_NONE;
      else if (index > DIR_EAST)
          index -= DIR_EAST;

      index--;
      behavior = MapGridGetMetatileBehaviorAt(x, y);

      if (ledgeBehaviorFuncs[index](behavior) == TRUE)
          return index + 1;

      return DIR_NONE;
}

/** static void SetObjectEventSpriteOamTableForLongGrass(struct ObjectEvent *objEvent, struct Sprite *sprite) */
export function SetObjectEventSpriteOamTableForLongGrass(objEvent: any, sprite: any): any {
  if (objEvent.disableCoveringGroundEffects)
          return;

      if (!MetatileBehavior_IsLongGrass(objEvent.currentMetatileBehavior))
          return;

      if (!MetatileBehavior_IsLongGrass(objEvent.previousMetatileBehavior))
          return;

      sprite.subspriteTableNum = 4;

      if (ElevationToPriority(objEvent.previousElevation) == 1)
          sprite.subspriteTableNum = 5;
}

/** static bool8 IsElevationMismatchAt(u8 elevation, s16 x, s16 y) */
export function IsElevationMismatchAt(elevation: any, x: any, y: any): any {
  let mapElevation: any = null;

      if (elevation == ELEVATION_TRANSITION)
          return FALSE;

      mapElevation = MapGridGetElevationAt(x, y);

      if (mapElevation == ELEVATION_TRANSITION || mapElevation == ELEVATION_MULTI_LEVEL)
          return FALSE;

      if (mapElevation != elevation)
          return TRUE;

      return FALSE;
}

/** static void UpdateObjectEventElevationAndPriority(struct ObjectEvent *objEvent, struct Sprite *sprite) */
export function UpdateObjectEventElevationAndPriority(objEvent: any, sprite: any): any {
  if (objEvent.fixedPriority)
          return;

      ObjectEventUpdateElevation(objEvent);

      sprite.subspriteTableNum = sElevationToSubspriteTableNum[objEvent.previousElevation];
      sprite.oam.priority = sElevationToPriority[objEvent.previousElevation];
}

/** static void InitObjectPriorityByElevation(struct Sprite *sprite, u8 elevation) */
export function InitObjectPriorityByElevation(sprite: any, elevation: any): any {
  sprite.subspriteTableNum = sElevationToSubspriteTableNum[elevation];
      sprite.oam.priority = sElevationToPriority[elevation];
}

/** u8 ElevationToPriority(u8 elevation) */
export function ElevationToPriority(elevation: any): any {
  return sElevationToPriority[elevation];
}

/** void ObjectEventUpdateElevation(struct ObjectEvent *objEvent) */
export function ObjectEventUpdateElevation(objEvent: any): any {
  let curElevation: any = MapGridGetElevationAt(objEvent.currentCoords.x, objEvent.currentCoords.y);
      let prevElevation: any = MapGridGetElevationAt(objEvent.previousCoords.x, objEvent.previousCoords.y);

      if (curElevation == ELEVATION_MULTI_LEVEL || prevElevation == ELEVATION_MULTI_LEVEL)
          return;

      objEvent.currentElevation = curElevation;

      if (curElevation != ELEVATION_TRANSITION && curElevation != ELEVATION_MULTI_LEVEL)
          objEvent.previousElevation = curElevation;
}

/** void SetObjectSubpriorityByElevation(u8 elevation, struct Sprite *sprite, u8 subpriority) */
export function SetObjectSubpriorityByElevation(elevation: any, sprite: any, subpriority: any): any {
  let tmp: any = sprite.centerToCornerVecY;
      let tmpa: any = sprite.y;
      let tmpb: any = gSpriteCoordOffsetY;
      let tmp2: any = (tmpa - tmp) + tmpb;
      let tmp3: any = (16 - (((tmp2 + 8) & 0xFF) >> 4)) * 2;
      sprite.subpriority = tmp3 + sElevationToSubpriority[elevation] + subpriority;
}

/** static void ObjectEventUpdateSubpriority(struct ObjectEvent *objEvent, struct Sprite *sprite) */
export function ObjectEventUpdateSubpriority(objEvent: any, sprite: any): any {
  if (objEvent.fixedPriority)
          return;

      SetObjectSubpriorityByElevation(objEvent.previousElevation, sprite, 1);
}

/** static bool8 AreElevationsCompatible(u8 a, u8 b) */
export function AreElevationsCompatible(a: any, b: any): any {
  if (a == ELEVATION_TRANSITION || b == ELEVATION_TRANSITION)
          return TRUE;

      if (a != b)
          return FALSE;

      return TRUE;
}

