/** static void DoFlaggedGroundEffects(struct ObjectEvent *objEvent, struct Sprite *sprite, u32 flags) */
export function DoFlaggedGroundEffects(objEvent: any, sprite: any, flags: any): any {
  let i: any = null;

      if (ObjectEventIsFarawayIslandMew(objEvent) == TRUE && !ShouldMewShakeGrass(objEvent))
          return;

      for (i = 0; i < ARRAY_COUNT(sGroundEffectFuncs); i++, flags >>= 1)
          if (flags & 1)
              sGroundEffectFuncs[i](objEvent, sprite);
}

/** void filters_out_some_ground_effects(struct ObjectEvent *objEvent, u32 *flags) */
export function filters_out_some_ground_effects(objEvent: any, flags: any): any {
  if (objEvent.disableCoveringGroundEffects)
      {
          objEvent.inShortGrass = 0;
          objEvent.inSandPile = 0;
          objEvent.inShallowFlowingWater = 0;
          objEvent.inHotSprings = 0;
          flags &= ~(GROUND_EFFECT_FLAG_HOT_SPRINGS
                    | GROUND_EFFECT_FLAG_SHORT_GRASS
                    | GROUND_EFFECT_FLAG_SAND_PILE
                    | GROUND_EFFECT_FLAG_SHALLOW_FLOWING_WATER
                    | GROUND_EFFECT_FLAG_TALL_GRASS_ON_MOVE);
      }
}

/** void FilterOutStepOnPuddleGroundEffectIfJumping(struct ObjectEvent *objEvent, u32 *flags) */
export function FilterOutStepOnPuddleGroundEffectIfJumping(objEvent: any, flags: any): any {
  if (objEvent.landingJump)
          flags &= ~GROUND_EFFECT_FLAG_PUDDLE;
}

/** static void DoGroundEffects_OnSpawn(struct ObjectEvent *objEvent, struct Sprite *sprite) */
export function DoGroundEffects_OnSpawn(objEvent: any, sprite: any): any {
  let flags: any = null;
      if (objEvent.triggerGroundEffectsOnMove && objEvent.localId != OBJ_EVENT_ID_CAMERA)
      {
          flags = 0;
          UpdateObjectEventElevationAndPriority(objEvent, sprite);
          GetAllGroundEffectFlags_OnSpawn(objEvent,flags);
          SetObjectEventSpriteOamTableForLongGrass(objEvent, sprite);
          DoFlaggedGroundEffects(objEvent, sprite, flags);
          objEvent.triggerGroundEffectsOnMove = FALSE;
          objEvent.disableCoveringGroundEffects = 0;
      }
}

/** static void DoGroundEffects_OnBeginStep(struct ObjectEvent *objEvent, struct Sprite *sprite) */
export function DoGroundEffects_OnBeginStep(objEvent: any, sprite: any): any {
  let flags: any = null;
      if (objEvent.triggerGroundEffectsOnMove && objEvent.localId != OBJ_EVENT_ID_CAMERA)
      {
          flags = 0;
          UpdateObjectEventElevationAndPriority(objEvent, sprite);
          GetAllGroundEffectFlags_OnBeginStep(objEvent,flags);
          SetObjectEventSpriteOamTableForLongGrass(objEvent, sprite);
          filters_out_some_ground_effects(objEvent,flags);
          DoFlaggedGroundEffects(objEvent, sprite, flags);
          objEvent.triggerGroundEffectsOnMove = FALSE;
          objEvent.disableCoveringGroundEffects = 0;
      }
}

/** static void DoGroundEffects_OnFinishStep(struct ObjectEvent *objEvent, struct Sprite *sprite) */
export function DoGroundEffects_OnFinishStep(objEvent: any, sprite: any): any {
  let flags: any = null;
      if (objEvent.triggerGroundEffectsOnStop && objEvent.localId != OBJ_EVENT_ID_CAMERA)
      {
          flags = 0;
          UpdateObjectEventElevationAndPriority(objEvent, sprite);
          GetAllGroundEffectFlags_OnFinishStep(objEvent,flags);
          SetObjectEventSpriteOamTableForLongGrass(objEvent, sprite);
          FilterOutStepOnPuddleGroundEffectIfJumping(objEvent,flags);
          DoFlaggedGroundEffects(objEvent, sprite, flags);
          objEvent.triggerGroundEffectsOnStop = 0;
          objEvent.landingJump = 0;
      }
}

/** bool8 FreezeObjectEvent(struct ObjectEvent *objectEvent) */
export function FreezeObjectEvent(objectEvent: any): any {
  if (objectEvent.heldMovementActive || objectEvent.frozen)
      {
          return TRUE;
      }
      else
      {
          objectEvent.frozen = TRUE;
          objectEvent.spriteAnimPausedBackup = gSprites[objectEvent.spriteId].animPaused;
          objectEvent.spriteAffineAnimPausedBackup = gSprites[objectEvent.spriteId].affineAnimPaused;
          gSprites[objectEvent.spriteId].animPaused = TRUE;
          gSprites[objectEvent.spriteId].affineAnimPaused = TRUE;
          return FALSE;
      }
}

/** void FreezeObjectEvents(void) */
export function FreezeObjectEvents(): any {
  let i: any = null;
      for (i = 0; i < OBJECT_EVENTS_COUNT; i++)
          if (gObjectEvents[i].active && i != gPlayerAvatar.objectEventId)
              FreezeObjectEvent(gObjectEvents[i]);
}

/** void FreezeObjectEventsExceptOne(u8 objectEventId) */
export function FreezeObjectEventsExceptOne(objectEventId: any): any {
  let i: any = null;
      for (i = 0; i < OBJECT_EVENTS_COUNT; i++)
          if (i != objectEventId && gObjectEvents[i].active && i != gPlayerAvatar.objectEventId)
              FreezeObjectEvent(gObjectEvents[i]);
}

/** void UnfreezeObjectEvent(struct ObjectEvent *objectEvent) */
export function UnfreezeObjectEvent(objectEvent: any): any {
  if (objectEvent.active && objectEvent.frozen)
      {
          objectEvent.frozen = 0;
          gSprites[objectEvent.spriteId].animPaused = objectEvent.spriteAnimPausedBackup;
          gSprites[objectEvent.spriteId].affineAnimPaused = objectEvent.spriteAffineAnimPausedBackup;
      }
}

/** void UnfreezeObjectEvents(void) */
export function UnfreezeObjectEvents(): any {
  let i: any = null;
      for (i = 0; i < OBJECT_EVENTS_COUNT; i++)
          if (gObjectEvents[i].active)
              UnfreezeObjectEvent(gObjectEvents[i]);
}

/** static void Step1(struct Sprite *sprite, u8 dir) */
export function Step1(sprite: any, dir: any): any {
  sprite.x += sDirectionToVectors[dir].x;
      sprite.y += sDirectionToVectors[dir].y;
}

/** static void Step2(struct Sprite *sprite, u8 dir) */
export function Step2(sprite: any, dir: any): any {
  sprite.x += 2 * sDirectionToVectors[dir].x;
      sprite.y += 2 * sDirectionToVectors[dir].y;
}

/** static void Step3(struct Sprite *sprite, u8 dir) */
export function Step3(sprite: any, dir: any): any {
  sprite.x += 2 * sDirectionToVectors[dir].x + sDirectionToVectors[dir].x;
      sprite.y += 2 * sDirectionToVectors[dir].y + sDirectionToVectors[dir].y;
}

/** static void Step4(struct Sprite *sprite, u8 dir) */
export function Step4(sprite: any, dir: any): any {
  sprite.x += 4 * sDirectionToVectors[dir].x;
      sprite.y += 4 * sDirectionToVectors[dir].y;
}

/** static void Step8(struct Sprite *sprite, u8 dir) */
export function Step8(sprite: any, dir: any): any {
  sprite.x += 8 * sDirectionToVectors[dir].x;
      sprite.y += 8 * sDirectionToVectors[dir].y;
}

/** static void SetSpriteDataForNormalStep(struct Sprite *sprite, u8 direction, u8 speed) */
export function SetSpriteDataForNormalStep(sprite: any, direction: any, speed: any): any {
  sprite.sDirection = direction;
      sprite.sSpeed = speed;
      sprite.sTimer = 0;
}

/** static bool8 NpcTakeStep(struct Sprite *sprite) */
export function NpcTakeStep(sprite: any): any {
  if (sprite.sTimer >= sStepTimes[sprite.sSpeed])
          return FALSE;

      sNpcStepFuncTables[sprite.sSpeed][sprite.sTimer](sprite, sprite.sDirection);

      sprite.sTimer++;

      if (sprite.sTimer < sStepTimes[sprite.sSpeed])
          return FALSE;

      return TRUE;
}

/** static void SetWalkSlowSpriteData(struct Sprite *sprite, u8 direction) */
export function SetWalkSlowSpriteData(sprite: any, direction: any): any {
  sprite.sDirection = direction;
      sprite.sTimer = 0;
      sprite.sNumSteps = 0;
}

/** static bool8 UpdateWalkSlowAnim(struct Sprite *sprite) */
export function UpdateWalkSlowAnim(sprite: any): any {
  if (!(sprite.sTimer & 1))
      {
          Step1(sprite, sprite.sDirection);
          sprite.sNumSteps++;
      }

      sprite.sTimer++;

      if (sprite.sNumSteps > 15)
          return TRUE;
      else
          return FALSE;
}

/** s16 GetFigure8YOffset(s16 idx) */
export function GetFigure8YOffset(idx: any): any {
  return sFigure8YOffsets[idx];
}

/** s16 GetFigure8XOffset(s16 idx) */
export function GetFigure8XOffset(idx: any): any {
  return sFigure8XOffsets[idx];
}

/** static void InitSpriteForFigure8Anim(struct Sprite *sprite) */
export function InitSpriteForFigure8Anim(sprite: any): any {
  sprite.data[6] = 0;
      sprite.data[7] = 0;
}

/** static bool8 AnimateSpriteInFigure8(struct Sprite *sprite) */
export function AnimateSpriteInFigure8(sprite: any): any {
  let finished: any = FALSE;

      switch(sprite.data[7])
      {
      case 0:
          sprite.x2 += GetFigure8XOffset(sprite.data[6]);
          sprite.y2 += GetFigure8YOffset(sprite.data[6]);
          break;
      case 1:
          sprite.x2 -= GetFigure8XOffset((FIGURE_8_LENGTH - 1) - sprite.data[6]);
          sprite.y2 += GetFigure8YOffset((FIGURE_8_LENGTH - 1) - sprite.data[6]);
          break;
      case 2:
          sprite.x2 -= GetFigure8XOffset(sprite.data[6]);
          sprite.y2 += GetFigure8YOffset(sprite.data[6]);
          break;
      case 3:
          sprite.x2 += GetFigure8XOffset((FIGURE_8_LENGTH - 1) - sprite.data[6]);
          sprite.y2 += GetFigure8YOffset((FIGURE_8_LENGTH - 1) - sprite.data[6]);
          break;
      }
      if (++sprite.data[6] == FIGURE_8_LENGTH)
      {
          sprite.data[6] = 0;
          sprite.data[7]++;
      }
      if (sprite.data[7] == 4)
      {
          sprite.y2 = 0;
          sprite.x2 = 0;
          finished = TRUE;
      }
      return finished;
}

/** static s16 GetJumpY(s16 i, u8 type) */
export function GetJumpY(i: any, _type: any): any {
  return sJumpYTable[_type][i];
}

/** static void SetJumpSpriteData(struct Sprite *sprite, u8 direction, u8 distance, u8 type) */
export function SetJumpSpriteData(sprite: any, direction: any, distance: any, _type: any): any {
  sprite.sDirection = direction;
      sprite.sDistance = distance;
      sprite.sJumpType = _type;
      sprite.sTimer = 0;
}

/** static u8 DoJumpSpriteMovement(struct Sprite *sprite) */
export function DoJumpSpriteMovement(sprite: any): any {
  const distanceToTime: any = [ 16, 16, 32,
      ];
      const distanceToShift: any = [ 0, 0, 1,
      ];
      let result: any = 0;

      if (sprite.sDistance != JUMP_DISTANCE_IN_PLACE)
          Step1(sprite, sprite.sDirection);

      sprite.y2 = GetJumpY(sprite.sTimer >> distanceToShift[sprite.sDistance], sprite.sJumpType);

      sprite.sTimer++;

      if (sprite.sTimer == distanceToTime[sprite.sDistance] >> 1)
          result = JUMP_HALFWAY;

      if (sprite.sTimer >= distanceToTime[sprite.sDistance])
      {
          sprite.y2 = 0;
          result = JUMP_FINISHED;
      }

      return result;
}

/** static u8 DoJumpSpecialSpriteMovement(struct Sprite *sprite) */
export function DoJumpSpecialSpriteMovement(sprite: any): any {
  const distanceToTime: any = [ 32, 32, 64,
      ];
      const distanceToShift: any = [ 1, 1, 2,
      ];
      let result: any = 0;

      if (sprite.sDistance != JUMP_DISTANCE_IN_PLACE && !(sprite.sTimer & 1))
          Step1(sprite, sprite.sDirection);

      sprite.y2 = GetJumpY(sprite.sTimer >> distanceToShift[sprite.sDistance], sprite.sJumpType);

      sprite.sTimer++;

      if (sprite.sTimer == distanceToTime[sprite.sDistance] >> 1)
          result = JUMP_HALFWAY;

      if (sprite.sTimer >= distanceToTime[sprite.sDistance])
      {
          sprite.y2 = 0;
          result = JUMP_FINISHED;
      }

      return result;
}

